-- Synchroniser les valeurs agrégées avec les données de test.
UPDATE touite SET note = (SELECT COALESCE(SUM(state), 0) FROM note2touite WHERE note2touite.touite_id = touite.id);
UPDATE users SET counter_touite = (SELECT COUNT(*) FROM touite WHERE touite.users_id = users.id);
COMMIT;
